<?php require_once __DIR__."/../config/app.php";require_role("Admin LP2M");$id=(int)($_GET["id"]??0);$st=$pdo->prepare("SELECT * FROM schemes WHERE id=?");$st->execute([$id]);$d=$st->fetch();if(!$d)exit("Data tidak ditemukan.");if($_SERVER["REQUEST_METHOD"]==="POST"){require_post_csrf();$d["name"]=post_string("name");$d["type"]=post_string("type");$d["max_fund"]=post_string("max_fund");$d["description"]=post_string("description");$d["is_active"]=isset($_POST["is_active"])?1:0;$pdo->prepare("UPDATE schemes SET name=?,type=?,max_fund=?,description=?,is_active=? WHERE id=?")->execute([$d["name"],$d["type"],$d["max_fund"],$d["description"],$d["is_active"],$id]);flash("success","Skema diperbarui.");redirect("index.php");}$pageTitle="Edit Skema";require __DIR__."/../partials/header.php";?><h3 class="fw-bold">Edit Skema</h3><form method="post" class="card p-4"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input class="form-control mb-3" name="name" value="<?=e($d["name"])?>" required><select class="form-select mb-3" name="type"><option <?= $d["type"]==="Penelitian"?"selected":""?>>Penelitian</option><option <?= $d["type"]==="Pengabdian"?"selected":""?>>Pengabdian</option></select><input class="form-control mb-3" type="number" name="max_fund" value="<?=e($d["max_fund"])?>"><textarea class="form-control mb-3" name="description"><?=e($d["description"])?></textarea><label><input type="checkbox" name="is_active" <?=$d["is_active"]?"checked":""?>> Aktif</label><div class="text-end mt-3"><a href="index.php" class="btn btn-light">Batal</a> <button class="btn btn-primary">Update</button></div></form><?php require __DIR__."/../partials/footer.php";?>